# Construct the output from the observed 3x3 panels and the demo-derived path rule.
grid = [[1]*30 for _ in range(30)]
rows = [1, 9, 16]
cols = [1, 10, 20]
colors = [[2,4,3],[3,6,9],[9,4,5]]
for pr, r0 in enumerate(rows):
    for pc, c0 in enumerate(cols):
        for r in range(r0, r0+6):
            for c in range(c0, c0+6):
                grid[r][c] = 8
        color = colors[pr][pc]
        for r in range(r0+2, r0+4):
            for c in range(c0+2, c0+4):
                grid[r][c] = color
# Ordered links: each source panel extends through the gap toward the next panel.
# A->B, B->C
for c in range(7,10):
    for r in range(3,5): grid[r][c] = 2
for c in range(16,20):
    for r in range(3,5): grid[r][c] = 4
# C->F, F->I
for r in range(7,9):
    for c in range(22,24): grid[r][c] = 3
for c in range(22,24): grid[15][c] = 9
# I->H, H->E
for c in range(16,20):
    for r in range(18,20): grid[r][c] = 5
for c in range(12,14): grid[15][c] = 4
# E->D, D->G
for c in range(7,10):
    for r in range(11,13): grid[r][c] = 6
for c in range(3,5): grid[15][c] = 3
# Bottom sequence
for i, value in enumerate([2,4,3,9,5,4,6,3,9]):
    grid[28][1+2*i] = value
assert len(grid)==30 and all(len(row)==30 for row in grid)
print('\n'.join(' '.join(map(str,row)) for row in grid))
